# v2.1 X13: NBTE's default management roles (placeholders the super admin edits
# in Settings → QA → Lookups → Management roles) and the old head/registrar/
# bursar/librarian contacts copied into ManagementStaff (contacts kept).
DEFAULT_ROLES = [
    # code, name, mandatory, ce, ict, order
    ("chief-executive", "Rector / Provost / Principal", True, True, False, 10),
    ("deputy-chief-executive", "Deputy Rector / Deputy Provost", False, False, False, 20),
    ("registrar", "Registrar", True, False, False, 30),
    ("bursar", "Bursar", True, False, False, 40),
    ("librarian", "Librarian", True, False, False, 50),
    ("head-of-ict", "Head of ICT", True, False, True, 60),
    ("dean-of-studies", "Dean of Studies", False, False, False, 70),
]
CONTACT_TO_ROLE = {"head_of_institution": "chief-executive", "registrar": "registrar", "bursar": "bursar",
                   "librarian": "librarian"}


def forwards(apps, schema_editor):
    Role = apps.get_model("institutions", "ManagementRole")
    Staff = apps.get_model("institutions", "ManagementStaff")
    Contact = apps.get_model("institutions", "InstitutionContact")
    roles = {}
    for code, name, mandatory, ce, ict, order in DEFAULT_ROLES:
        roles[code], _ = Role.objects.get_or_create(code=code, defaults={
            "name": name, "is_mandatory": mandatory, "is_chief_executive": ce, "is_ict_head": ict,
            "sort_order": order, "requires_email": True, "requires_phone": True})
    for c in Contact.objects.filter(kind__in=CONTACT_TO_ROLE, is_current=True).order_by("id"):
        name = (c.name or "").strip()
        if not name:
            continue
        role = roles[CONTACT_TO_ROLE[c.kind]]
        if Staff.objects.filter(institution_id=c.institution_id, role=role, is_current=True).exists():
            continue
        value = (c.value or "").strip()
        Staff.objects.create(institution_id=c.institution_id, role=role, full_name=name[:150],
                             email=value if "@" in value else "", phone="" if "@" in value else value[:30])


def backwards(apps, schema_editor):
    apps.get_model("institutions", "ManagementStaff").objects.all().delete()


